<script setup lang="ts">
/**
 * DecisionCard: one decision the server offers (`ActionView`), with what it does, what to inspect first
 * and its form or button. The request it sends carries the decision key of the state shown here, so the
 * server refuses it if the task has changed in the meantime.
 *
 * Props:
 * - `action`: the `ActionView`; its form, when present, is generated by ActionForm.
 * - `busy`: a request is in flight or waits for the server; inputs stay editable, sending is disabled.
 * - `sending`: this action is being sent.
 * - `issues`: field problems from the last submit.
 *
 * Emits `run` with the form drafts (empty for an action without a form).
 *
 * Slots:
 * - `default`: what to inspect before deciding (the digest to approve, the files to authorize).
 * - `field-extra`: passed on to ActionForm.
 */
import { useId } from 'vue';
import type { ActionView, FormField } from '../../../src/server/api-types';
import type { FieldIssue, FormDrafts } from '../api/actions';
import ActionButton from './ActionButton.vue';
import ActionForm from './ActionForm.vue';

defineOptions({ name: 'DecisionCard' });

withDefaults(defineProps<{ action: ActionView; busy?: boolean; sending?: boolean; issues?: readonly FieldIssue[] }>(), {
  busy: false,
  sending: false,
  issues: () => [],
});

const emit = defineEmits<{ run: [drafts: FormDrafts] }>();

const slots = defineSlots<{
  default?: () => unknown;
  'field-extra'?: (props: { field: FormField; append: (line: string) => void }) => unknown;
}>();

const titleId = useId();
</script>

<template>
  <section
    :aria-labelledby="titleId"
    class="flex flex-col gap-3 rounded-lg border border-default bg-default p-4"
    :data-decision="action.id"
  >
    <header class="flex flex-col gap-1">
      <h3 :id="titleId" class="text-base font-semibold text-highlighted">{{ action.label }}</h3>
      <p class="text-sm text-toned">{{ action.description }}</p>
    </header>
    <div v-if="slots.default" class="text-sm text-default"><slot /></div>
    <ActionForm
      v-if="action.form"
      :action="action"
      :busy="busy"
      :sending="sending"
      :issues="issues"
      @submit="drafts => emit('run', drafts)"
    >
      <template #field-extra="extra"><slot name="field-extra" v-bind="extra" /></template>
    </ActionForm>
    <ActionButton
      v-else
      :action="action"
      :busy="busy"
      :sending="sending"
      :described-by="titleId"
      @run="emit('run', {})"
    />
  </section>
</template>
